MERGE INTO INFRANEXUM_IAM_PERMISSION p USING (SELECT '019ffbda-1501-7111-8101-000000000001' ID, 'integrations.connector.read' CODE FROM dual) s ON (p.CODE=s.CODE AND p.ORGANIZATION_ID IS NULL) WHEN NOT MATCHED THEN INSERT (ID,ORGANIZATION_ID,CODE,RESOURCE_TYPE,ACTION_NAME,SENSITIVITY,SCOPE_KIND,SYSTEM_DEFINED,ACTIVE,CREATED_AT,UPDATED_AT,DELETED_AT) VALUES (s.ID,NULL,s.CODE,'integration_connector','read','NORMAL','PLATFORM',1,1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,NULL);
MERGE INTO INFRANEXUM_IAM_PERMISSION p USING (SELECT '019ffbda-1502-7222-8202-000000000002' ID, 'integrations.connector.resume' CODE FROM dual) s ON (p.CODE=s.CODE AND p.ORGANIZATION_ID IS NULL) WHEN NOT MATCHED THEN INSERT (ID,ORGANIZATION_ID,CODE,RESOURCE_TYPE,ACTION_NAME,SENSITIVITY,SCOPE_KIND,SYSTEM_DEFINED,ACTIVE,CREATED_AT,UPDATED_AT,DELETED_AT) VALUES (s.ID,NULL,s.CODE,'integration_connector','resume','CRITICAL','PLATFORM',1,1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,NULL);
