MERGE INTO INFRANEXUM_IAM_ROLE_PERMISSION rp USING (SELECT '019ffbda-1001-7e80-9ec8-7580467e9a85' ROLE_ID, p.ID PERMISSION_ID FROM INFRANEXUM_IAM_PERMISSION p WHERE p.ORGANIZATION_ID IS NULL AND p.CODE LIKE 'integrations.%') s ON (rp.ROLE_ID=s.ROLE_ID AND rp.PERMISSION_ID=s.PERMISSION_ID) WHEN NOT MATCHED THEN INSERT (ROLE_ID,PERMISSION_ID) VALUES (s.ROLE_ID,s.PERMISSION_ID);
